#include <iostream>
#include <stdexcept>
#include <string>

// Legacy C++98: void safeAdd(int a, int b) throw();
// Modern C++17: use noexcept
void safeAdd(int a, int b) noexcept {
    std::cout << "Sum: " << (a + b) << "\n";
}

// Function that may throw
int parseDigit(char c) {
    if (c < '0' || c > '9') {
        throw std::invalid_argument(std::string("Not a digit: ") + c);
    }
    return c - '0';
}

int main() {
    safeAdd(10, 20);

    try {
        int val1 = parseDigit('5');
        std::cout << "Parsed: " << val1 << "\n";
        int val2 = parseDigit('x');
        std::cout << "Parsed: " << val2 << "\n";
    } catch (const std::exception& ex) {
        std::cout << "Caught exception: " << ex.what() << "\n";
    }

    return 0;
}

#include <iostream>
#include <string>
#include <stdexcept>

int findIndex(const std::string& str, char target) {
    for (size_t i = 0; i < str.size(); ++i) {
        if (str[i] == target) return static_cast<int>(i);
    }
    return -1; // Expected condition handled locally with sentinel
}

int hexCharToDec(char ch) {
    if (ch >= '0' && ch <= '9') return ch - '0';
    if (ch >= 'A' && ch <= 'F') return ch - 'A' + 10;
    if (ch >= 'a' && ch <= 'f') return ch - 'a' + 10;
    throw std::invalid_argument(std::string("Invalid hex character: ") + ch);
}

int main() {
    std::string s = "hello";
    int idx = findIndex(s, 'z');
    if (idx == -1) {
        std::cout << "'z' not found (normal branch with if).\n";
    }

    try {
        std::cout << "Dec for 'B': " << hexCharToDec('B') << "\n";
        int val = hexCharToDec('G');
        std::cout << "Dec for 'G': " << val << "\n";
    } catch (const std::invalid_argument& ex) {
        std::cout << "Caught exceptional error: " << ex.what() << "\n";
    }
    return 0;
}
